const forbidden = ['ssn', 'itin', 'passport', 'idphoto', 'selfie', 'bankpassword', 'password', 'otp', '2fa'];
const body = $input.first().json.body || {};
const clean = {};
for (const [key, value] of Object.entries(body)) {
  const k = key.toLowerCase().replace(/[^a-z]/g, '');
  if (forbidden.some((f) => k.includes(f))) {
    clean[key] = '[CLIENT-ONLY]';
  } else {
    clean[key] = value;
  }
}
return [{ json: { profile: clean, instruction: 'Run the USA business onboarding workflow for the attached data pack. Validate the pack, classify risk, research suitable banks and processors, then prefill the best-fit application. The moment you reach identity verification or any attestation, end your reply with the exact marker HANDOVER_REQUIRED followed by a client handover note.' } }];
